INSERT INTO `addons` (`id`, `product_id`, `image`, `name`, `config_name`, `short_name`, `directory`, `description`, `price`, `current_version`, `article_link`, `installation_by`, `uninstall_version`, `unistall_by`, `addon_prod`, `addon_ver`, `last_update`, `current_stage`, `product_order`, `created_at`, `updated_at`) VALUES
(1, '0', 'uploads/addon_images/shqra_images.jpeg', 'Smart Hospital QR Attendance', 'qrattendance-config', 'shqra', 'qr_code_attendance', 'QR Code Attendance addon adds automated Staff attendance using QR/Barcode module in Smart Hospital. Using this module Staff can submit their attendance by just scanning their ID Card.', 0.00, NULL, 'https://go.smart-hospital.in/qr-attendance', NULL, NULL, NULL, NULL, NULL, '2025-04-17 12:36:55', 0, 1, '2025-01-13 13:10:06', '2025-06-16 13:22:46'),
(2, '0', 'uploads/addon_images/shtfa_images.jpeg', 'Smart Hospital Two Factor Authentication', 'google-authenticate-config', 'shtfa', 'two_factor_authentication', 'Two Factor Authentication addon adds Two Factor Authentication module in Smart Hospital. Using this module you can enhance login security of your Smart Hospital users.', 0.00, NULL, 'https://go.smart-hospital.in/2fa', NULL, NULL, NULL, NULL, NULL, '2025-04-08 15:25:34', 0, 2, '2024-09-07 10:45:18', '2025-06-16 13:22:49'),
(3, '0', 'uploads/addon_images/shmb_images.jpeg', 'Smart Hospital Multi Branch', 'multibranch-config', 'shmb', 'multi_branch', 'Multi Branch addon adds Multi Branch module in Smart Hospital. Using this module Superadmin user can add other any number of hospital/branches.', 0.00, NULL, 'https://go.smart-hospital.in/multi-branch', NULL, NULL, NULL, NULL, NULL, '2025-04-17 12:37:02', 0, 3, '2024-09-07 10:45:18', '2025-06-16 13:22:52'),
(4, '0', 'uploads/addon_images/shsf_images.jpeg', 'Smart Hospital Survey Form', 'survey-form-config', 'shsf', 'survey_form', 'Smart Hospital Survey Form addon adds Survey module in Smart Hospital. Using it you can create new surveys for patient, staff or public users.', 0.00, NULL, 'https://go.smart-hospital.in/survey-form', NULL, NULL, NULL, NULL, NULL, '2025-04-17 12:36:55', 0, 1, '2025-01-13 13:10:06', '2025-06-16 13:22:46'),
(5, '0', 'uploads/addon_images/shwm_images.jpeg', 'Smart Hospital Whatsapp Messaging', 'whatsapp-messaging-config', 'shwm', 'whatsapp_messaging', 'Smart Hospital WhatsApp Messaging addon adds WhatsApp messaging module in Smart Hospital. Using this module you can send notification or direct messages to patient/staff WhatsApp number on their mobile.', 0.00, NULL, 'https://go.smart-hospital.in/whatsapp-messaging', NULL, NULL, NULL, '', '', '2026-01-09 12:37:27', 0, 0, '2025-01-13 12:10:06', '2026-01-27 07:39:33');
